-- OmniWork PostgreSQL schema. The API also creates these tables automatically.
create table if not exists users (id text primary key,name text not null,email text unique not null,role text not null,avatar_url text not null,skills text[] not null default '{}',created_at timestamptz not null default now());
create table if not exists work_contexts (id text primary key,user_id text unique not null references users(id) on delete cascade,status text not null check(status in ('Focus','Available','Away')),project text not null default '',task text not null default '',message text not null default '',interrupt_for text not null default '',expires_at text,created_at timestamptz not null,updated_at timestamptz not null);
create table if not exists status_history (id text primary key,user_id text not null references users(id) on delete cascade,status text not null,message text not null,created_at timestamptz not null);
create table if not exists work_events (id text primary key,team_id text not null,source text not null,category text not null,title text not null,detail text not null default '',project text not null default '',target_user text,action_required boolean not null default false,time_display text not null default 'Just now',created_at timestamptz not null);
create table if not exists integrations (user_id text not null references users(id) on delete cascade,id text not null,name text not null,icon text not null,connected boolean not null default false,last_synced_status text,last_synced_at text,primary key(user_id,id));
create table if not exists queued_messages (id text primary key,sender_id text not null,sender_name text not null,sender_avatar text not null,recipient_id text not null references users(id) on delete cascade,recipient_name text not null,urgency text not null,body text not null,created_at timestamptz not null,read boolean not null default false);
